contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint prevTimestamp, uint callValue) public payable {
        require(callValue == 10 ether, "call must send exactly 10 ether");
        require(address(this).balance >= callValue, "test contract lacks ether");

        if (prevTimestamp > 0) {
            (bool ok, bytes memory data) = address(c).call{value: 0}("");
            require(!ok, "unexpected success setting timestamp");
        }

        bool reverted;
        try c.fallback{value: callValue}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(c.pastBlockTime() == block.timestamp);
        } else {
            assert(c.pastBlockTime() <= block.timestamp);
        }
    }

    receive() external payable {}
}

