        assert(beforeTime <= timeAfterFirst);
        assert(beforeBalance + amount1 >= afterBalance);
        if (ok1) {
            assert(timeAfterFirst == snapshot);
        }
        if (ok2 && ok1) {
            assert(timeAfterSecond == block.timestamp);
            assert(timeAfterSecond > timeAfterFirst);
        }
    }

    receive() external payable {}
}

