contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 timeAdvance) public payable {
        require(address(this).balance >= 10 ether, "not enough balance");
        require(timeAdvance > 0, "must advance time");

        uint256 oldPastBlockTime = c.pastBlockTime();
        uint256 oldBalance = address(c).balance;
        bool isMultipleOfFifteen = block.number % 15 == 0;

        // Make a first successful call to be able to advance time and then test the reversal behavior
        uint256 firstAdvance = oldPastBlockTime + timeAdvance + 1;
        // Ensure the first call's timestamp is strictly later than oldPastBlockTime
        // In practice we cannot control block.timestamp, but we can use the same timestamp for both calls.
        // The rule checks: if timestamp > pastBlockTime then it must succeed.
        // We'll make one call, record its result, then make a second call with the same timestamp to check the revert condition.
        bool reverted1;
        try c.fallback{value: 10 ether}() {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }

        uint256 after1 = c.pastBlockTime();
        uint256 bal1 = address(c).balance;

        // First call must succeed (since block.timestamp > oldPastBlockTime)
        assert(!reverted1);
        assert(after1 == block.timestamp);
        if (isMultipleOfFifteen) {
            assert(bal1 == 0);
        } else {
            assert(bal1 == oldBalance + 10 ether);
        }

        // Second call with the same timestamp must revert
        bool reverted2;
        try c.fallback{value: 10 ether}() {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }

        uint256 after2 = c.pastBlockTime();
        uint256 bal2 = address(c).balance;

        // The second call must revert because block.timestamp == pastBlockTime
        assert(reverted2);
        assert(after2 == after1);
        assert(bal2 == bal1);
        // The general rule: if timestamp > pastBlockTime, call succeeds and updates timestamp; otherwise reverts.
    }

    receive() external payable {}
}

