contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint ts, uint bal) public payable {
        require(address(this).balance >= 10 ether);

        // Setup: establish a past block time strictly before the current block timestamp.
        // We cannot set block.timestamp directly; instead use a view call only.
        // If ts == block.timestamp, need to ensure precondition ts < block.timestamp, so
        // choose ts such that ts < block.timestamp by using a value derived from current timestamp.
        // However, params are arbitrary. Use ts under a require.
        // We use ts as the previous timestamp, and require block.timestamp > ts.
        // This makes the call well-defined.
        ts = block.timestamp - 1;
        require(block.timestamp > ts);

        uint before = c.pastBlockTime();
        require(before <= ts);

        uint cBalBefore = address(c).balance;

        bool reverted;
        try c.fallback{value: 10 ether}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterTs = c.pastBlockTime();
        uint cBalAfter = address(c).balance;

        bool divisible = block.number % 15 == 0;

        // General rule: the call with 10 ether should not revert,
        // pastBlockTime is updated to the current block timestamp,
        // and the balance either drops to zero (if block.number % 15 == 0)
        // or increases by exactly 10 ether (otherwise).
        if (!reverted) {
            assert(afterTs == block.timestamp);
            if (divisible) {
                assert(cBalAfter == 0);
            } else {
                assert(cBalAfter == cBalBefore + 10 ether);
            }
        } else {
            assert(false);
        }
    }
}

