    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(amount == 10 ether, "must send exactly 10 ether");
        require(address(this).balance >= amount, "test must hold enough ether");

        uint256 cBalBefore = address(c).balance;
        uint256 pastBefore = c.pastBlockTime();
        uint256 callerBalBefore = address(this).balance;

        bool reverted;
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 cBalAfter = address(c).balance;
        uint256 pastAfter = c.pastBlockTime();
        uint256 callerBalAfter = address(this).balance;

        assert(
            (reverted && cBalAfter == cBalBefore && pastAfter == pastBefore && callerBalAfter == callerBalBefore) ||
                (!reverted && pastAfter == block.timestamp &&
                    (cBalAfter == cBalBefore + amount ||
                        (cBalAfter == 0 &&
                            callerBalAfter == callerBalBefore + amount + cBalBefore)))
        );
    }

    receive() external payable {}
}

