        // block.timestamp > beforeTime is expected in a normal test environment.
        bool successful;
        try c.{value: amount}() {
            successful = true;
        } catch {
            successful = false;
        }

        // The wrong-value call must revert, and the correct-value call must succeed.
        assert(wrongReverted && successful && c.pastBlockTime() == block.timestamp);
    }

    receive() external payable {}
}

