contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint64 timestamp, uint blockNum) public payable {
        require(amount == 10 ether);
        require(address(this).balance >= amount);

        // Ensure the test can control block.timestamp and block.number constraints
        // by only proceeding if a call with these values can potentially succeed.
        require(timestamp > c.pastBlockTime());

        // Force the block timestamp to be the parameter.
        require(block.timestamp == timestamp || block.timestamp > c.pastBlockTime());

        // Attempt fallback with exactly 10 ether.
        bool reverted;
        uint256 beforeBalance = address(this).balance;
        uint256 cBeforeBalance = address(c).balance;
        uint256 beforePast = c.pastBlockTime();

        address payable sender = payable(address(this));
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = address(this).balance;
        uint256 cAfterBalance = address(c).balance;
        uint256 afterPast = c.pastBlockTime();

        if (reverted) {
            // If reverted, state and balances must be unchanged.
            assert(afterPast == beforePast && afterBalance == beforeBalance && cAfterBalance == cBeforeBalance);
        } else {
            // Successful call requires exactly 10 ether and updates pastBlockTime.
            assert(amount == 10 ether && afterPast == block.timestamp);
            if (block.number % 15 == 0) {
                // Caller receives the entire previous contract balance.
                assert(afterBalance == beforeBalance - amount + cBeforeBalance);
                assert(cAfterBalance == 0);
            } else {
                // No transfer occurs.
                assert(afterBalance == beforeBalance - amount);
                assert(cAfterBalance == cBeforeBalance + amount);
            }
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(amount == 10 ether);
        require(address(this).balance >= amount);

        uint256 beforePast = c.pastBlockTime();
        uint256 beforeSelf = address(this).balance;
        uint256 beforeC = address(c).balance;

        bool reverted;
        uint256 newPast;

        (bool success, ) = address(c).call{value: amount}("");
        reverted = !success;
        newPast = c.pastBlockTime();

        uint256 afterSelf = address(this).balance;
        uint256 afterC = address(c).balance;

        if (reverted) {
            // A reverted call must leave pastBlockTime and all balances unchanged.
            assert(newPast == beforePast && afterSelf == beforeSelf && afterC == beforeC);
        } else {
            // A successful call must update pastBlockTime to the call's timestamp.
            assert(newPast == block.timestamp);
            if (block.number % 15 == 0) {
                // The entire previous balance moved from c to this caller.
                assert(afterC == 0 && afterSelf == beforeSelf + beforeC - amount);
            } else {
                // The 10 ether stayed in c and nothing extra moved.
                assert(afterC == beforeC + amount && afterSelf == beforeSelf - amount);
            }
        }
    }

    receive() external payable {}
}

